<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\QuestionLearning;
use App\Domain\QuestionLearning\Entity\QuestionNote;use App\Domain\QuestionLearning\Repository\QuestionNoteRepositoryInterface;use App\Infrastructure\Persistence\Doctrine\QuestionLearning\Entity\QuestionNoteRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineQuestionNoteRepository implements QuestionNoteRepositoryInterface { public function __construct(private readonly EntityManagerInterface $entityManager) {} public function findForUserQuestion(string $userId, string $questionId): ?QuestionNote { $record = $this->entityManager->getRepository(QuestionNoteRecord::class)->findOneBy(['userId' => $userId, 'questionId' => $questionId]); return $record instanceof QuestionNoteRecord ? $this->map($record) : null; } public function save(QuestionNote $note): void { $record = $this->entityManager->getRepository(QuestionNoteRecord::class)->findOneBy(['userId' => $note->userId, 'questionId' => $note->questionId]) ?? new QuestionNoteRecord(); $record->id = $note->id; $record->userId = $note->userId; $record->questionId = $note->questionId; $record->content = $note->content(); $record->createdAt = $note->createdAt; $record->updatedAt = $note->updatedAt(); $this->entityManager->persist($record); $this->entityManager->flush(); } public function deleteForUserQuestion(string $userId, string $questionId): void { $record = $this->entityManager->getRepository(QuestionNoteRecord::class)->findOneBy(['userId' => $userId, 'questionId' => $questionId]); if ($record instanceof QuestionNoteRecord) { $this->entityManager->remove($record); $this->entityManager->flush(); } } private function map(QuestionNoteRecord $record): QuestionNote { return new QuestionNote($record->id, $record->userId, $record->questionId, $record->content, $record->createdAt, $record->updatedAt); } }
